#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <stdint.h>

#define FEATURE_REMOTE_SCHEMA    (1 << 0)
#define FEATURE_LOCAL_CACHE      (1 << 1)
#define FEATURE_VALIDATION       (1 << 2)
#define FEATURE_COMPRESSION      (1 << 3)

#define MAX_URI_LEN 2048
#define ALLOWED_SCHEMES_COUNT 1

static const char *ALLOWED_SCHEMES[] = {"https://"};

typedef struct {
    uint32_t features;
    char schema_base_uri[MAX_URI_LEN];
    int (*uri_validator)(const char *uri);
} serializer_config_t;

typedef struct {
    char *data;
    size_t len;
} fetch_buffer_t;

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t total = size * nmemb;
    fetch_buffer_t *buf = (fetch_buffer_t *)userp;
    if (buf->len + total > 1048576) return 0; /* 1MB limit */
    char *tmp = realloc(buf->data, buf->len + total + 1);
    if (!tmp) return 0;
    buf->data = tmp;
    memcpy(buf->data + buf->len, contents, total);
    buf->len += total;
    buf->data[buf->len] = '\0';
    return total;
}

static int default_uri_validator(const char *uri) {
    /* Check that URI uses an allowed scheme */
    for (int i = 0; i < ALLOWED_SCHEMES_COUNT; i++) {
        if (strncmp(uri, ALLOWED_SCHEMES[i], strlen(ALLOWED_SCHEMES[i])) == 0) {
            return 1;
        }
    }
    return 0;
}

static int is_internal_network(const char *uri) {
    /* Block requests to internal/private networks */
    const char *host_start = strstr(uri, "://");
    if (!host_start) return 1;
    host_start += 3;

    if (strncmp(host_start, "127.", 4) == 0) return 1;
    if (strncmp(host_start, "10.", 3) == 0) return 1;
    if (strncmp(host_start, "192.168.", 8) == 0) return 1;
    if (strncmp(host_start, "172.16.", 7) == 0) return 1;
    if (strncmp(host_start, "169.254.", 8) == 0) return 1;
    if (strncmp(host_start, "localhost", 9) == 0) return 1;
    if (strncmp(host_start, "[::1]", 5) == 0) return 1;
    if (strncmp(host_start, "0.", 2) == 0) return 1;
    if (strncmp(host_start, "[0:", 3) == 0) return 1;
    if (strncmp(host_start, "[fc", 3) == 0) return 1;
    if (strncmp(host_start, "[fd", 3) == 0) return 1;

    return 0;
}

static int validate_fetch_uri(const serializer_config_t *config, const char *uri) {
    /* Validation is ALWAYS enforced regardless of feature flags */
    if (config->uri_validator && !config->uri_validator(uri)) {
        return 0;
    }

    if (is_internal_network(uri)) {
        return 0;
    }

    return 1;
}

static char *fetch_remote_schema(const serializer_config_t *config, const char *schema_ref) {
    char full_uri[MAX_URI_LEN];

    if (schema_ref[0] == '/') {
        snprintf(full_uri, sizeof(full_uri), "%s%s", config->schema_base_uri, schema_ref);
    } else {
        snprintf(full_uri, sizeof(full_uri), "%s", schema_ref);
    }

    if (!validate_fetch_uri(config, full_uri)) {
        fprintf(stderr, "URI validation failed: %s\n", full_uri);
        return NULL;
    }

    CURL *curl = curl_easy_init();
    if (!curl) return NULL;

    fetch_buffer_t buf = {0};
    curl_easy_setopt(curl, CURLOPT_URL, full_uri);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &buf);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 0L);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_PROTOCOLS, CURLPROTO_HTTPS);

    CURLcode res = curl_easy_perform(curl);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        free(buf.data);
        return NULL;
    }

    return buf.data;
}

typedef struct {
    char *type_name;
    char *schema_uri;
    char *payload;
    size_t payload_len;
} serialized_message_t;

static serialized_message_t *deserialize_message(const char *raw, size_t raw_len) {
    serialized_message_t *msg = calloc(1, sizeof(serialized_message_t));
    if (!msg) return NULL;

    /* Simple binary format: [type_len:2][type][uri_len:2][uri][payload] */
    if (raw_len < 4) { free(msg); return NULL; }

    uint16_t type_len;
    memcpy(&type_len, raw, sizeof(type_len));
    /* Ensure the type field AND the following uri_len field are within bounds.
     * We need: 2 (type_len field) + type_len (type) + 2 (uri_len field) <= raw_len.
     * Use size_t arithmetic to avoid overflow. */
    if ((size_t)type_len + 4 > raw_len) { free(msg); return NULL; }
    msg->type_name = strndup(raw + 2, type_len);
    if (!msg->type_name) { free(msg); return NULL; }

    uint16_t uri_len;
    memcpy(&uri_len, raw + 2 + type_len, sizeof(uri_len));
    /* Ensure the uri field is within bounds using size_t arithmetic. */
    if ((size_t)type_len + (size_t)uri_len + 4 > raw_len) {
        free(msg->type_name);
        free(msg);
        return NULL;
    }
    msg->schema_uri = strndup(raw + 4 + type_len, uri_len);
    if (!msg->schema_uri) {
        free(msg->type_name);
        free(msg);
        return NULL;
    }

    size_t header_size = (size_t)4 + type_len + uri_len;
    msg->payload_len = raw_len - header_size;
    if (msg->payload_len > 0) {
        msg->payload = malloc(msg->payload_len);
        if (!msg->payload) {
            free(msg->type_name);
            free(msg->schema_uri);
            free(msg);
            return NULL;
        }
        memcpy(msg->payload, raw + header_size, msg->payload_len);
    }

    return msg;
}

int process_message(const serializer_config_t *config, const char *raw, size_t raw_len) {
    serialized_message_t *msg = deserialize_message(raw, raw_len);
    if (!msg) return -1;

    char *schema = NULL;

    uint32_t required_for_fetch = FEATURE_REMOTE_SCHEMA;

    if ((config->features & required_for_fetch) && msg->schema_uri[0] != '\0') {
        if (config->features & FEATURE_LOCAL_CACHE) {
            /* Try local cache first - simplified */
            char cache_path[512];
            snprintf(cache_path, sizeof(cache_path), "/var/cache/schemas/%s.json", msg->type_name);
            /* In production, validate type_name has no path traversal */
            if (strchr(msg->type_name, '/') == NULL && strchr(msg->type_name, '\\') == NULL) {
                FILE *f = fopen(cache_path, "r");
                if (f) {
                    fseek(f, 0, SEEK_END);
                    long fsize = ftell(f);
                    if (fsize > 0 && fsize < 1048576) {
                        fseek(f, 0, SEEK_SET);
                        schema = malloc((size_t)fsize + 1);
                        if (schema) {
                            size_t nread = fread(schema, 1, (size_t)fsize, f);
                            schema[nread] = '\0';
                        }
                    }
                    fclose(f);
                }
            }
        }

        if (!schema) {
            schema = fetch_remote_schema(config, msg->schema_uri);
        }
    }

    /* Process with schema... */
    printf("Processed message type: %s\n", msg->type_name);

    free(schema);
    free(msg->type_name);
    free(msg->schema_uri);
    free(msg->payload);
    free(msg);
    return 0;
}

serializer_config_t *create_default_config(const char *base_uri) {
    serializer_config_t *config = calloc(1, sizeof(serializer_config_t));
    if (!config) return NULL;

    /* Default: enable remote schema + validation + local cache */
    config->features = FEATURE_REMOTE_SCHEMA | FEATURE_LOCAL_CACHE | FEATURE_VALIDATION;
    config->uri_validator = default_uri_validator;

    if (base_uri) {
        strncpy(config->schema_base_uri, base_uri, MAX_URI_LEN - 1);
    }

    return config;
}

serializer_config_t *create_config_from_env(void) {
    serializer_config_t *config = calloc(1, sizeof(serializer_config_t));
    if (!config) return NULL;

    const char *features_str = getenv("SERIALIZER_FEATURES");
    if (features_str) {
        uint32_t requested = (uint32_t)strtoul(features_str, NULL, 0);
        /* Always force VALIDATION on if REMOTE_SCHEMA is enabled */
        if (requested & FEATURE_REMOTE_SCHEMA) {
            requested |= FEATURE_VALIDATION;
        }
        config->features = requested;
    } else {
        config->features = FEATURE_REMOTE_SCHEMA | FEATURE_LOCAL_CACHE | FEATURE_VALIDATION;
    }

    const char *base = getenv("SCHEMA_BASE_URI");
    if (base) {
        strncpy(config->schema_base_uri, base, MAX_URI_LEN - 1);
    }

    config->uri_validator = default_uri_validator;
    return config;
}
